use std::collections::{HashMap, HashSet};
use zbus::zvariant::{OwnedValue, Structure};

pub(super) type MenuId = (u32, u32);
pub(super) type Item = HashMap<String, OwnedValue>;
pub(super) type Menus = HashMap<MenuId, Vec<Item>>;

pub(super) enum Search {
    Load(u32),
    Found(MenuId, usize, usize),
    Invalid,
}

pub(super) fn find(
    menus: &Menus,
    groups: &HashSet<u32>,
    root: MenuId,
    root_depth: usize,
    label: &str,
) -> Search {
    let mut pending = vec![(root, root_depth)];
    let mut visited = HashSet::new();
    let mut found = None;
    while let Some((id, depth)) = pending.pop() {
        if depth >= 16 || !visited.insert(id) {
            return Search::Invalid;
        }
        if !groups.contains(&id.0) {
            return Search::Load(id.0);
        }
        let Some(items) = menus.get(&id) else {
            return Search::Invalid;
        };
        for (index, item) in items.iter().enumerate() {
            if let Some(section) = item.get(":section") {
                let Some(section) = link(section) else {
                    return Search::Invalid;
                };
                pending.push((section, depth + 1));
            }
            if item.get(":submenu").is_some_and(|v| link(v).is_none()) {
                return Search::Invalid;
            }
            if let Some(value) = item.get("label") {
                let Ok(text) = <&str>::try_from(value) else {
                    return Search::Invalid;
                };
                if strip_mnemonic(text).trim() == label.trim() {
                    if found.is_some() || item.contains_key(":section") {
                        return Search::Invalid;
                    }
                    found = Some((id, index, depth));
                }
            }
        }
    }
    match found {
        Some((menu, item, depth)) => Search::Found(menu, item, depth),
        None => Search::Invalid,
    }
}

pub(super) fn link(value: &OwnedValue) -> Option<MenuId> {
    let structure = <&Structure<'_>>::try_from(value).ok()?;
    let [group, menu] = structure.fields() else {
        return None;
    };
    Some((u32::try_from(group).ok()?, u32::try_from(menu).ok()?))
}

pub(super) fn strip_mnemonic(text: &str) -> String {
    let mut chars = text.chars();
    let mut result = String::new();
    while let Some(ch) = chars.next() {
        if ch == '_' {
            if let Some(next) = chars.next() {
                result.push(next);
            }
        } else {
            result.push(ch);
        }
    }
    result
}

use agent_desktop_core::AdapterError;

pub(crate) const NODE_LIMIT: usize = 2048;
pub(crate) const DEPTH_LIMIT: usize = 8;

pub(crate) struct Inspected {
    pub(crate) name: Option<String>,
    pub(crate) selection: bool,
    pub(crate) selectable: bool,
}

pub(crate) trait ItemReader {
    type Node: Clone;

    fn inspect(&mut self, node: &Self::Node) -> Result<Inspected, AdapterError>;

    fn children(&mut self, node: &Self::Node) -> Result<Vec<Self::Node>, AdapterError>;
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Container<N> {
    pub(crate) node: N,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct Hit<N> {
    pub(crate) item: N,
    pub(crate) container: Option<Container<N>>,
    pub(crate) row: Option<N>,
    pub(crate) own: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum Search<N> {
    Found(Hit<N>),
    Ambiguous,
    NotFound { selectable: bool },
    Incomplete,
}

pub(crate) fn name_matches(name: &str, wanted: &str) -> bool {
    name.trim().to_lowercase() == wanted.trim().to_lowercase()
}

struct Pending<N> {
    node: N,
    depth: usize,
    container: Option<Container<N>>,
    row: Option<N>,
}

pub(crate) fn search<R: ItemReader>(
    reader: &mut R,
    root: &R::Node,
    wanted: &str,
) -> Result<Search<R::Node>, AdapterError> {
    let mut stack = vec![Pending {
        node: root.clone(),
        depth: 0,
        container: None,
        row: None,
    }];
    let mut seen = 0;
    let mut selectable = false;
    let mut incomplete = false;
    let mut found: Option<Hit<R::Node>> = None;
    while let Some(pending) = stack.pop() {
        if seen >= NODE_LIMIT {
            incomplete = true;
            break;
        }
        seen += 1;
        let inspected = match reader.inspect(&pending.node) {
            Ok(inspected) => inspected,
            Err(error) if pending.depth == 0 => return Err(error),
            Err(_) => {
                incomplete = true;
                continue;
            }
        };
        selectable |= inspected.selectable;
        let matched = inspected
            .name
            .as_deref()
            .is_some_and(|name| name_matches(name, wanted));
        if matched {
            if found.is_some() {
                return Ok(Search::Ambiguous);
            }
            found = Some(Hit {
                item: pending.node,
                container: pending.container,
                row: pending.row,
                own: pending.depth == 0,
            });
            continue;
        }
        let children = match reader.children(&pending.node) {
            Ok(children) => children,
            Err(error) if pending.depth == 0 => return Err(error),
            Err(_) => {
                incomplete = true;
                continue;
            }
        };
        if pending.depth >= DEPTH_LIMIT {
            incomplete |= !children.is_empty();
            continue;
        }
        for child in children.into_iter().rev() {
            let container = if inspected.selection {
                Some(Container {
                    node: pending.node.clone(),
                })
            } else {
                pending.container.clone()
            };
            let row = if inspected.selection {
                Some(child.clone())
            } else {
                pending.row.clone()
            };
            stack.push(Pending {
                node: child,
                depth: pending.depth + 1,
                container,
                row,
            });
        }
    }
    if incomplete {
        return Ok(Search::Incomplete);
    }
    Ok(match found {
        _ if incomplete => Search::Incomplete,
        Some(hit) => Search::Found(hit),
        None => Search::NotFound { selectable },
    })
}

